          "content": "先不用背名詞。近地面空氣受氣壓梯度力由高壓朝低壓移動，並受地球自轉、摩擦與地形影響而偏轉。 本技能聚焦在「由氣壓差判斷近地面空氣流動方向」；專屬判準是「近地面空氣受氣壓梯度力由高壓朝低壓移動，並受地球自轉、摩擦與地形影響而偏轉」。看到題目時，先圈出觀測對象、時間、位置與單位。"
